source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json, statistics, math

for tag, path, skey in [('s015', '/root/autodl-tmp/pacs/profiling_output_bf16_ds_imp_s015/profiling_results.json', '0.15'), ('s025', '/root/autodl-tmp/pacs/profiling_output_bf16_ds_imp_s025/profiling_results.json', '0.25')]:
    d = json.load(open(path))
    ppii = d['per_problem_ii'][skey]
    print(f'=== {tag} ===')
    print(f'per_problem_ii count: {len(ppii)}')
    print(f'sample keys: {list(ppii[0].keys())}')

    null_count = 0
    nan_count = 0
    for p in ppii:
        for k2 in ['ii_high','ii_mid','ii_low']:
            v = p.get(k2)
            if v is None:
                null_count += 1
            elif isinstance(v, float) and math.isnan(v):
                nan_count += 1
    print(f'  null: {null_count}, NaN: {nan_count}')

    for phase_key in ['ii_high', 'ii_mid', 'ii_low']:
        vals = [p[phase_key] for p in ppii if p.get(phase_key) is not None and not (isinstance(p[phase_key], float) and math.isnan(p[phase_key]))]
        if vals:
            print(f'  {phase_key}: n={len(vals)}, mean={statistics.mean(vals):.6f}, median={statistics.median(vals):.6f}, min={min(vals):.6f}, max={max(vals):.6f}, std={statistics.stdev(vals):.6f}')

    paired_grads = []
    for p in ppii:
        h = p.get('ii_high')
        l = p.get('ii_low')
        if h is not None and l is not None:
            if not (isinstance(h, float) and math.isnan(h)) and not (isinstance(l, float) and math.isnan(l)):
                paired_grads.append(l - h)
    if paired_grads:
        print(f'  gradient_paired (low-high): mean={statistics.mean(paired_grads):.6f}, median={statistics.median(paired_grads):.6f}')
    print()
"
